async function renderProfileReviewQueue(banner = '') {
  const curApproved = vaultRows.filter(v => String(v.auth_status || '').toLowerCase().startsWith('authenticated') && v.profile_approval_status === 'APPROVED');
  const curPendingRev = vaultRows.filter(v => String(v.auth_status || '').toLowerCase().startsWith('authenticated') && v.profile_approval_status !== 'APPROVED' && v.profile_approval_status !== 'PAUSED');
  const curPaused = vaultRows.filter(v => String(v.auth_status || '').toLowerCase().startsWith('authenticated') && v.profile_approval_status === 'PAUSED');

  const pendingLines = curPendingRev.map(v => {
    const revUrl = getProfileReviewUrl(v.site_name, v.profile_review_url || v.portal_url);
    const notePart = v.custom_preferences_note ? `\n  📝 _Custom Note: ${v.custom_preferences_note}_` : '';
    return (
      `⏳ *${v.site_name}* (\`${v.login_method || 'Logged In'}\`)\n` +
      `  • *Filled:* Master Resume PDF + 29 Skills + 3 Certs + EU/AU/Remote/India Prefs\n` +
      `  • *Gate:* \`🔒 Auto-Apply LOCKED until you approve\`\n` +
      `  • 🔗 [🔍 Click to Check & Review ${v.site_name} Profile](${revUrl})` + notePart
    );
  }).join('\n\n') || '• _No profiles currently waiting for review!_';

  const approvedLines = curApproved.map(v => {
    const revUrl = getProfileReviewUrl(v.site_name, v.profile_review_url || v.portal_url);
    return `🟢 *${v.site_name}* — \`Approved (Auto-Apply Active)\` • [View Profile](${revUrl})`;
  }).join('\n') || '• _None approved yet — tap Approve below after checking your profile links!_';

  const pausedLines = curPaused.length > 0
    ? `\n\n⏸️ *On Hold / Paused (${curPaused.length}):*\n` + curPaused.map(v => `• *${v.site_name}* ([View Profile](${getProfileReviewUrl(v.site_name, v.profile_review_url)}))`).join('\n')
    : '';

  const kb = [];
  for (const v of curPendingRev) {
    kb.push([
      { text: `✅ Approve ${v.site_name} & Start Applying`, callback_data: `prof_app:${v.site_name}` },
      { text: `✏️ Edit ${v.site_name}`, callback_data: `prof_edit:${v.site_name}` }
    ]);
  }
  for (const v of curPaused) {
    kb.push([
      { text: `✅ Approve & Resume ${v.site_name}`, callback_data: `prof_app:${v.site_name}` },
      { text: `✏️ Edit ${v.site_name}`, callback_data: `prof_edit:${v.site_name}` }
    ]);
  }
  if (curPendingRev.length > 1) {
    kb.push([{ text: `✅ Approve ALL ${curPendingRev.length} Pending Profiles & Start Applying`, callback_data: 'prof_app_all' }]);
  }
  kb.push([{ text: '🛠️ Re-Fill & Re-Upload Master Resume to All Portals', callback_data: 'cmd:complete_all_profiles' }]);
  kb.push([{ text: '📋 View All 23 Portals', callback_data: 'cred_list:all:0' }]);
  kb.push([{ text: '▴ Back to Compact Menu', callback_data: 'nav:home' }]);

  await sendOrEdit(
    (banner ? `${banner}\n━━━━━━━━━━━━━━━━━━━━━━━━\n` : '') +
    `👤 *Portal Profile Check, Review & Auto-Apply Approval Gate*\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `📄 *Uploaded Master Resume:* [Sumanto_Banerjee-Master_Resume.pdf](${MASTER_PDF_URL})\n` +
    `🎯 *Preferences Synced:* \`Senior Data Analyst / BI / Analytics Engineer\` • \`EU, Australia, Global Remote, UAE & India\`\n\n` +
    `⏳ *1. Filled & Waiting for Your Review (${curPendingRev.length}) — Auto-Apply LOCKED:*\n` +
    `${pendingLines}\n\n` +
    `🟢 *2. Approved & Actively Applying (${curApproved.length}):*\n` +
    `${approvedLines}` +
    `${pausedLines}\n\n` +
    `👉 _Click any profile review link above to verify your filled profile, uploaded Master Resume, and preferences. Once verified, tap **✅ Approve** to start applying to jobs!_`,
    kb
  );
}

// Helper to render the Paginated 23-Portal Vault List
async function renderPortalList(filterMode, pageIdx) {
  let list = vaultRows;
  if (filterMode === 'pending') list = pendingPortals;
  else if (filterMode === 'review') list = pendingReviewPortals;
  else if (filterMode === 'auth') list = approvedPortals;

  const pageSize = 8;
  const totalPages = Math.max(1, Math.ceil(list.length / pageSize));
  const safePage = Math.max(0, Math.min(pageIdx, totalPages - 1));
  const slice = list.slice(safePage * pageSize, (safePage + 1) * pageSize);

  const filterLabel = filterMode === 'pending'
    ? `🟡 Needs Login (${pendingPortals.length})`
    : (filterMode === 'review'
      ? `⏳ Profile Filled — Awaiting Your Review (${pendingReviewPortals.length})`
      : (filterMode === 'auth' ? `🟢 Approved & Applying (${approvedPortals.length})` : `📋 All Portals (${vaultRows.length})`));

  const siteLines = slice.map((v) => {
    const globalIdx = vaultRows.findIndex(x => x.site_name === v.site_name);
    const isAuth = String(v.auth_status || '').toLowerCase().startsWith('authenticated');
    const appStat = String(v.profile_approval_status || '').trim();
    const revUrl = getProfileReviewUrl(v.site_name, v.profile_review_url || v.portal_url);
    let icon = '🟡';
    let profTag = ' _(Needs Login)_';
    if (isAuth) {
      if (appStat === 'APPROVED') {
        icon = '🟢';
        profTag = ' _(Approved & Applying)_';
      } else if (appStat === 'PAUSED') {
        icon = '⏸️';
        profTag = ' _(Paused)_';
      } else {
        icon = '⏳';
        profTag = ' _(Profile Filled — Tap to Review & Approve)_';
      }
    }
    const urlPart = isAuth ? `[Review Profile](${revUrl})` : (v.portal_url ? `[Open Site](${v.portal_url})` : '');
    return `${icon} *#${globalIdx + 1} ${v.site_name}*${profTag} ${urlPart}`;
  }).join('\n');

  const kb = [
    [
      { text: `${filterMode === 'review' ? '🔘' : '⚪'} Review (${pendingReviewPortals.length})`, callback_data: 'cred_list:review:0' },
      { text: `${filterMode === 'auth' ? '🔘' : '⚪'} Approved (${approvedPortals.length})`, callback_data: 'cred_list:auth:0' }
    ],
    [
      { text: `${filterMode === 'pending' ? '🔘' : '⚪'} Login (${pendingPortals.length})`, callback_data: 'cred_list:pending:0' },
      { text: `${filterMode === 'all' ? '🔘' : '⚪'} All (${vaultRows.length})`, callback_data: 'cred_list:all:0' }
    ]
  ];

  for (const v of slice) {
    const globalIdx = vaultRows.findIndex(x => x.site_name === v.site_name);
    const isAuth = String(v.auth_status || '').toLowerCase().startsWith('authenticated');
    const appStat = String(v.profile_approval_status || '').trim();
    const icon = !isAuth ? '🟡' : (appStat === 'APPROVED' ? '🟢' : (appStat === 'PAUSED' ? '⏸️' : '⏳'));
    const statusShort = !isAuth ? 'Needs Login' : (appStat === 'APPROVED' ? 'Approved & Active' : (appStat === 'PAUSED' ? 'Paused' : 'Review & Approve'));
    kb.push([{ text: `${icon} #${globalIdx + 1} ${v.site_name} (${statusShort})`, callback_data: `cred_idx:${globalIdx}` }]);
  }

  if (totalPages > 1) {
    const navRow = [];
    if (safePage > 0) navRow.push({ text: `⬅️ Page ${safePage}`, callback_data: `cred_list:${filterMode}:${safePage - 1}` });
    if (safePage < totalPages - 1) navRow.push({ text: `Page ${safePage + 2} ➡️`, callback_data: `cred_list:${filterMode}:${safePage + 1}` });
    kb.push(navRow);
  }

  kb.push([{ text: `👤 Review & Approve Pending Profiles (${pendingReviewPortals.length})`, callback_data: 'cmd:profile_reviews' }]);
  kb.push([{ text: '🛠️ Re-Fill & Sync All Logged-In Profiles', callback_data: 'cmd:complete_all_profiles' }]);
  kb.push([{ text: '▴ Back to Compact Menu', callback_data: 'nav:home' }]);

  await sendOrEdit(
    `🔐 *Portal Authentication, Profile Filler & Approval Gate*\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `*Filter:* ${filterLabel} — *Page ${safePage + 1}/${totalPages}*\n\n` +
    `${siteLines || '• None in this filter'}\n\n` +
    `_Tap any portal button below to log in, review its filled profile link, or approve it for Auto-Apply:_`,
    kb
  );
}

// Helper to render Learned Rules Manager (Unlearn / Delete)
async function renderRulesManager(customBanner = '') {
  const isLiSec = s => String(s || '').toLowerCase().includes('linkedin');
  const isClSec = s => String(s || '').toLowerCase().includes('cover') || String(s || '').toLowerCase() === 'cl';
  const resRules = allLearnedRules.filter(r => !isClSec(r.section_name) && !isLiSec(r.section_name));
  const clRules = allLearnedRules.filter(r => isClSec(r.section_name));
  const liRulesList = allLearnedRules.filter(r => isLiSec(r.section_name));

  const resList = resRules.map(r => `• *#${r.id}* \`[${r.section_name}]\`: ${String(r.rule_instruction).slice(0, 95)}`).join('\n') || '• _No active Resume learned rules_';
  const clList = clRules.map(r => `• *#${r.id}* \`[${r.section_name}]\`: ${String(r.rule_instruction).slice(0, 95)}`).join('\n') || '• _No active Cover Letter learned rules_';
  const liList = liRulesList.map(r => `• *#${r.id}* \`[${r.section_name}]\`: ${String(r.rule_instruction).slice(0, 95)}`).join('\n') || '• _No active LinkedIn learned rules_';

  const kb = [];
  for (const r of allLearnedRules.slice(0, 10)) {
    const typeLabel = isLiSec(r.section_name) ? 'LinkedIn' : (isClSec(r.section_name) ? 'CL' : `Resume:${r.section_name}`);
    kb.push([{ text: `🗑️ Unlearn Rule #${r.id} (${typeLabel})`, callback_data: `unlearn_id:${r.id}` }]);
  }
  kb.push([{ text: `🗑️ Delete ALL Resume Rules (${resRules.length})`, callback_data: 'unlearn_bulk:resume' }]);
  kb.push([{ text: `🗑️ Delete ALL Cover Letter Rules (${clRules.length})`, callback_data: 'unlearn_bulk:cl' }]);
  kb.push([{ text: `🗑️ Delete ALL LinkedIn Rules (${liRulesList.length})`, callback_data: 'unlearn_bulk:linkedin' }]);
  kb.push([{ text: '⚠️ Delete ALL Rules Totally (Wipe All)', callback_data: 'unlearn_bulk:all' }]);
  kb.push([{ text: '▴ Back to Compact Menu', callback_data: 'nav:home' }]);

  await sendOrEdit(
    (customBanner ? `${customBanner}\n━━━━━━━━━━━━━━━━━━━━━━━━\n` : '') +
    `🧠 *Learned Rules Manager (Unlearn / Delete)*\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `📄 *Resume Rules (${resRules.length} Active):*\n${resList}\n\n` +
    `✉️ *Cover Letter Rules (${clRules.length} Active):*\n${clList}\n\n` +
    `🤝 *LinkedIn Post Rules (${liRulesList.length} Active):*\n${liList}\n\n` +
    `_Tap any rule button below to unlearn it immediately, or wipe rules by category:_`,
    kb
  );
}

// Helpers for LinkedIn Activity Log, Approval Queue & Daily EOD Summary
function computeLiMetrics() {
  const isApproved = r => /^approved/i.test(r.approval_status) || r.execution_status === 'Posted / Sent' || r.execution_status === 'Reacted Only';
  const isPending = r => /pending|reworked/i.test(r.approval_status);
  const isDenied = r => /denied|skipped|rejected/i.test(r.approval_status);

  const connSent = liLogs.filter(r => r.activity_type === 'Connection Request' && isApproved(r)).length + Number(liStats.connection_requests_sent || 0);
  const followSent = liLogs.filter(r => r.activity_type === 'Follow Request' && isApproved(r)).length + Number(liStats.follow_requests_sent || 0);
  const followAccepted = liLogs.filter(r => r.activity_type === 'Follow Accepted' && isApproved(r)).length + Number(liStats.follow_requests_accepted || 0);
  const msgsSent = liLogs.filter(r => (r.activity_type === 'Direct Message (Slide-In)' || r.activity_type === 'Follow Accepted') && isApproved(r)).length + Number(liStats.messages_sent || 0);
  const reactionsGiven = liLogs.filter(r => r.reaction_type && r.reaction_type !== '—' && isApproved(r)).length + Number(liStats.reactions_given || 0);
  const commentsPosted = liLogs.filter(r => r.activity_type === 'Post Comment' && isApproved(r)).length + Number(liStats.comments_posted || 0);
  const profileViews = Math.max(8, liLogs.filter(r => r.activity_type === 'Profile View / Research').length + Number(liStats.profile_views || 8));

  const pendingList = liLogs.filter(isPending);
  const approvedList = liLogs.filter(isApproved);
  const deniedList = liLogs.filter(isDenied);
  const singlePostRulesCount = liLogs.filter(r => r.rule_scope === 'This Post Only').length;
  const liGlobalRules = allLearnedRules.filter(r => String(r.section_name || '').toLowerCase().includes('linkedin'));
  const globalRulesCount = Math.max(liGlobalRules.length, liLogs.filter(r => r.rule_scope === 'Global Learned Rule').length);

  const eodRow = {
    'Date': todayIso,
    'Connection Requests Sent': connSent,
    'Follow Requests Sent': followSent,
    'Follow Requests Accepted': followAccepted,
    'Messages / DMs Sent': msgsSent,
    'Reactions Given on Posts': reactionsGiven,
    'Comments Posted': commentsPosted,
    'Other Activities (Profile Views / Searches / Drafts)': `${pendingList.length} Pending Approval Drafts + ${profileViews} Target Insiders Researched`,
    'Drafts Generated Today': liLogs.length,
    'Approved Count': approvedList.length,
    'Denied Count': deniedList.length,
    'Global Rules Learned': globalRulesCount,
    'Single-Post Rules Applied': singlePostRulesCount,
    'Daily Summary Notes & Top Companies': `Active across Amex, Axtria, Google, Stripe, Nagarro, Razorpay, EY, HDFC, Crisil, Siemens Energy, Nielsen. ${pendingList.length} items pending approval.`
  };

  return {
    connSent, followSent, followAccepted, msgsSent, reactionsGiven, commentsPosted, profileViews,
    pendingList, approvedList, deniedList, singlePostRulesCount, globalRulesCount, liGlobalRules, eodRow
  };
}

