// Helper to build Referral & HR Follow-Up Items across Job Application Sheet + Reference Sheet
function isPlaceholderHrLabel(val) {
  const s = String(val || '').trim().toLowerCase();
  if (!s) return true;
  if (s === 'n/a' || s === 'na' || s === 'none' || s === '-' || s === 'tbd' || s === 'unknown') return true;
  if (s.includes('talent acquisition') || s.includes('recruiting team') || s.includes('recruitment team') || s.includes('hr team') || s.includes('hiring team') || s.includes('careers team') || s.endsWith(' ta') || s.includes('& internal audit ta')) return true;
  return false;
}

function rowQualifiesForFollowUp(r) {
  const refCol = String(r['Reference'] || '').trim();
  const appliedFrom = String(r['Applied From'] || '').trim().toLowerCase();
  const hrCol = String(r['HR'] || '').trim();
  const hrEmailCol = String(r['HR Email'] || '').trim();
  const statusCol = String(r['Status'] || '').trim().toLowerCase();
  const notesCol = String(r['Notes'] || '').trim().toLowerCase();
  const isRef = Boolean(refCol && !['n/a', 'na', 'none', '-'].includes(refCol.toLowerCase())) ||
    appliedFrom.includes('referral') || appliedFrom.includes('reference') ||
    statusCol.includes('referral') || notesCol.includes('referred by') || notesCol.includes('via referral');
  const sentToHr = appliedFrom.includes('email') || appliedFrom.includes('sent to hr') ||
    appliedFrom.includes('hr mail') || appliedFrom.includes('direct hr') ||
    Boolean(hrEmailCol && hrEmailCol.includes('@')) ||
    Boolean(hrCol && !isPlaceholderHrLabel(hrCol));
  const ongoingHrConv = statusCol.includes('hr ') || statusCol.includes('recruiter') ||
    statusCol.includes('interview') || statusCol.includes('conversation') ||
    notesCol.includes('ongoing conversation') || notesCol.includes('hr replied') ||
    notesCol.includes('recruiter replied') || notesCol.includes('mail conversation') ||
    notesCol.includes('email thread');
  return { qualifies: Boolean(isRef || sentToHr || ongoingHrConv), isReferral: isRef, sentToHr, ongoingHrConv };
}

function getReferralFollowUpItems() {
  const refMap = {};
  for (const rc of refContacts) {
    refMap[String(rc.company_name || '').trim().toLowerCase()] = rc;
  }

  const items = [];
  for (const r of jobRows) {
    const sNo = String(r['S. No.'] || '').trim();
    if (!sNo) continue;
    const comp = String(r['Company'] || '').trim();
    if (!comp) continue;
    const title = String(r['Position - Title'] || 'Target Role').trim();
    const refCol = String(r['Reference'] || '').trim();
    const hrCol = String(r['HR'] || '').trim();
    const hrEmailCol = String(r['HR Email'] || '').trim();
    const statusCol = String(r['Status'] || '').trim();
    const followUpDate = String(r['Follow up Date'] || '').trim();
    const matchedRef = refMap[comp.toLowerCase()] || {};

    const q = rowQualifiesForFollowUp(r);
    const isReferral = q.isReferral;
    const hasNamedHr = q.sentToHr || q.ongoingHrConv;

    if (q.qualifies) {
      const contactName = refCol || hrCol || matchedRef.referrer_name || 'Hiring Team';
      const contactEmail = hrEmailCol || matchedRef.referrer_email || '';
      const contactSocial = matchedRef.referrer_social || '';
      items.push({
        type: 'job',
        sNo,
        company: comp,
        title,
        contactName,
        contactEmail,
        contactSocial,
        isReferral,
        followUpDate: followUpDate || todayMDY,
        notes: String(r['Notes'] || '')
      });
    }
  }

  // Also include Reference Sheet rows that have an email or active note (like Axtria -> Ashish Chandra)
  for (const rc of refContacts) {
    const alreadyInJobs = items.some(x => x.company.toLowerCase() === String(rc.company_name || '').toLowerCase());
    if (!alreadyInJobs && (rc.referrer_email || rc.referrer_name)) {
      items.push({
        type: 'refsheet',
        sNo: `REF-${rc.company_name}`,
        company: rc.company_name,
        title: 'Senior Data Analyst / Analytics Role',
        contactName: rc.referrer_name,
        contactEmail: rc.referrer_email || '',
        contactSocial: rc.referrer_social || '',
        isReferral: true,
        followUpDate: todayMDY,
        notes: rc.notes || ''
      });
    }
  }
  return items;
}

