else if (action.startsWith('/enrich') || action === 'cmd:enrich') {
  let enriched = 0;
  for (const r of jobRows) {
    const sNo = String(r['S. No.'] || '').trim();
    if (!sNo) continue;
    const title = String(r['Position - Title'] || '').trim();
    const jd = String(r['Position - Description'] || '').trim();
    const comp = String(r['Company'] || '').trim();
    const status = String(r['Status'] || '').trim();
    if (!title && !jd && !comp && !status) continue;

    const patch = { 'S. No.': sNo };
    let changed = false;
    if (!String(r['Resume_id'] || '').trim()) { patch['Resume_id'] = `RES-${sNo}`; changed = true; }
    if (!String(r['Industry'] || '').trim()) { patch['Industry'] = 'Technology & Data Analytics'; changed = true; }
    if (!String(r['Location'] || '').trim()) { patch['Location'] = 'India (Hybrid / Remote)'; changed = true; }
    const appOn = String(r['Applied On'] || '').trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(appOn)) {
      const [y, m, d] = appOn.split('-').map(Number);
      patch['Applied On'] = `${m}/${d}/${y}`;
      changed = true;
    }
    const folUp = String(r['Follow up Date'] || '').trim();
    const qFup = rowQualifiesForFollowUp(r);
    if (!qFup.qualifies) {
      if (folUp) {
        patch['Follow up Date'] = '';
        changed = true;
      }
      const hrVal = String(r['HR'] || '').trim();
      if (hrVal && isPlaceholderHrLabel(hrVal)) {
        patch['HR'] = '';
        changed = true;
      }
    } else if (/^\d{4}-\d{2}-\d{2}$/.test(folUp)) {
      const [y, m, d] = folUp.split('-').map(Number);
      patch['Follow up Date'] = `${m}/${d}/${y}`;
      changed = true;
    }
    if (changed) {
      sheetUpdates.push(patch);
      enriched++;
    }
  }
  await sendOrEdit(
